from pathlib import Path
import json,base64
p=Path(__file__).resolve().parent
m=json.loads((p/'manifest.json').read_text());duration={'gold':18,'silver-equator':12,'silver-meridian':30};direction={'gold':1,'silver-equator':-1,'silver-meridian':1}
def image(name):return 'data:image/png;base64,'+base64.b64encode((p/(name+'.png')).read_bytes()).decode()
def svg(animated):
 defs='<defs><clipPath id="rear"><rect x="0" y="0" width="256" height="128"/></clipPath><clipPath id="front"><rect x="0" y="128" width="256" height="128"/></clipPath>'
 for s in m['layers']:defs+=f'<image id="layer-{s["name"]}" href="{image(s["name"])}" width="256" height="256"/>'
 defs+='<clipPath id="gold-rear"><rect x="-128" y="-128" width="512" height="256" transform="rotate(-30 128 128)"/></clipPath><clipPath id="gold-front"><rect x="-128" y="128" width="512" height="256" transform="rotate(-30 128 128)"/></clipPath><clipPath id="meridian-rear"><rect x="128" y="-128" width="256" height="512"/></clipPath><clipPath id="meridian-front"><rect x="-128" y="-128" width="256" height="512"/></clipPath>'
 defs+='<mask id="gold-mask"><rect width="256" height="256" fill="black"/><ellipse cx="113" cy="69" rx="108" ry="30" transform="rotate(-30 113 69)" fill="none" stroke="white" stroke-width="8"/></mask></defs>'
 defs=defs.replace('<image id="layer-gold"', '<image id="gold-source" mask="url(#gold-mask)"')
 defs=defs.replace('<image id="layer-silver-meridian"', '<image id="meridian-source"')
 defs=defs.replace('</defs>', '<g id="layer-gold" transform="translate(15 59)"><ellipse cx="113" cy="69" rx="108" ry="30" transform="rotate(-30 113 69)" fill="none" stroke="#27251d" stroke-width="10"/><ellipse cx="113" cy="69" rx="108" ry="30" transform="rotate(-30 113 69)" fill="none" stroke="#ab9567" stroke-width="7"/><use href="#gold-source"/></g><g id="layer-silver-meridian" transform="translate(84 20)"><use href="#meridian-source"/></g></defs>')
 def arc(name,half):
  motion=f'<animateTransform attributeName="transform" type="rotate" from="0 128 128" to="{direction[name]*360} 128 128" dur="{duration[name]}s" repeatCount="indefinite"/>' if animated else ''
  clip=('gold-'+half) if name=='gold' else ('meridian-'+half) if name=='silver-meridian' else half
  return f'<g data-ring="{name}" data-half="{half}"><g clip-path="url(#{clip})"><use href="#layer-{name}"/></g>{motion}</g>'
 body=''.join(arc(n,'rear') for n in duration)+'<use href="#layer-globe"/>'+''.join(arc(n,'front') for n in duration)+'<use href="#layer-frame"/>'
 return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" width="512" height="512" role="img" aria-label="Plenitude com três arcos girando independentemente"><title>Plenitude — arcos independentes</title>'+defs+body+'</svg>'
(p/'animation.svg').write_text(svg(True))
controls=''
for name,label in [('gold','Arco dourado'),('silver-equator','Equador prateado'),('silver-meridian','Meridiano prateado')]:
 controls+=f'<div class="control"><label for="period-{name}">{label}</label><div class="inputs"><input id="period-{name}" data-period="{name}" type="range" min="6" max="40" value="{duration[name]}" aria-label="Segundos por volta do {label.lower()}"><output id="value-{name}">{duration[name]} s</output><select data-direction="{name}" aria-label="Sentido do {label.lower()}"><option value="1" {"selected" if direction[name]>0 else ""}>Horário</option><option value="-1" {"selected" if direction[name]<0 else ""}>Anti-horário</option></select></div></div>'
original='data:image/png;base64,'+base64.b64encode((p.parents[2]/'07-plenitude.png').read_bytes()).decode()
html='''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Plenitude • arcos independentes</title><style>
*{box-sizing:border-box}body{margin:0;font:14px/1.5 var(--font-sans,system-ui);color:var(--foreground,#e9e5db)}p{margin:0 0 16px;color:var(--muted-foreground,#a9a9a9)}.layout{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:18px;align-items:center}.scene{background:#101219;border:1px solid #36332e;border-radius:16px;padding:22px;position:relative}.scene svg,.scene img{display:block;width:100%;height:auto;aspect-ratio:1}.scene img{display:none}.scene.reference svg{display:none}.scene.reference img{display:block}.caption{font-size:11px;letter-spacing:.12em;text-align:center;color:#a99364;margin-top:10px}.control{padding:12px 0;border-bottom:1px solid var(--border,#36332e)}.control label{display:block;margin-bottom:8px;font:18px Georgia,serif}.inputs{display:grid;grid-template-columns:minmax(50px,1fr) 34px 110px;gap:8px;align-items:center}input{width:100%;accent-color:#b69a65}output{font-size:12px;white-space:nowrap;color:var(--muted-foreground,#aaa)}button,select{font:inherit;border:1px solid var(--border,#45403a);border-radius:8px;background:var(--card,#17191e);color:inherit;padding:8px;cursor:pointer}select{width:100%;font-size:12px}.buttons{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0 0}.foot{font-size:12px;margin-top:18px}.paper{background:#ddd4ba}.paper .caption{color:#69542e}.hint{font-size:12px;margin:12px 0 0}@media(max-width:560px){.layout{grid-template-columns:1fr;gap:4px}.scene{max-width:380px;width:100%;margin:auto;padding:22px}.control{padding:10px 0}.inputs{grid-template-columns:minmax(70px,1fr) 34px 114px}}
</style><p>O dourado gira em 18 s, o equador em sentido contrário em 12 s e o meridiano em 30 s. A moldura e o globo permanecem fixos.</p><div class="layout"><div class="scene" id="scene">'''+svg(False)+f'<img src="{original}" alt="Arte original da última esfera"><div class="caption" id="caption">PLENITUDE · ARCOS INDEPENDENTES</div></div><div>'+controls+'''<div class="buttons"><button id="play">Pausar</button><button id="reset">Restaurar</button><button id="reference">Ver original</button><button id="background">Fundo claro</button></div><p class="hint">Menos segundos = giro mais rápido. Ajuste cada arco separadamente.</p></div></div><p class="foot">Camadas separadas no PixelLab, recompostas com metades dianteiras e traseiras. Rotação no plano da imagem com centro comum; a separação reconstrói partes que estavam ocultas na arte original.</p><script>
const periods={gold:18,'silver-equator':12,'silver-meridian':30},directions={gold:1,'silver-equator':-1,'silver-meridian':1},angles={gold:0,'silver-equator':0,'silver-meridian':0};let playing=!matchMedia('(prefers-reduced-motion: reduce)').matches,last=0,reference=false;
function draw(){document.querySelectorAll('[data-ring]').forEach(g=>g.setAttribute('transform','rotate('+angles[g.dataset.ring]+' 128 128)'));document.getElementById('play').textContent=playing?'Pausar':'Reproduzir';document.getElementById('play').setAttribute('aria-pressed',String(playing))}
document.querySelectorAll('[data-period]').forEach(input=>input.oninput=()=>{periods[input.dataset.period]=Number(input.value);document.getElementById('value-'+input.dataset.period).textContent=input.value+' s'});document.querySelectorAll('[data-direction]').forEach(input=>input.onchange=()=>{directions[input.dataset.direction]=Number(input.value)});
document.getElementById('play').onclick=()=>{playing=!playing;draw()};document.getElementById('reset').onclick=()=>{Object.assign(periods,{gold:18,'silver-equator':12,'silver-meridian':30});Object.assign(directions,{gold:1,'silver-equator':-1,'silver-meridian':1});Object.keys(angles).forEach(k=>angles[k]=0);document.querySelectorAll('[data-period]').forEach(i=>{i.value=periods[i.dataset.period];i.oninput()});document.querySelectorAll('[data-direction]').forEach(i=>i.value=directions[i.dataset.direction]);draw()};document.getElementById('reference').onclick=()=>{reference=!reference;document.getElementById('scene').classList.toggle('reference',reference);document.getElementById('reference').textContent=reference?'Ver animação':'Ver original';document.getElementById('caption').textContent=reference?'ARTE ORIGINAL':'PLENITUDE · ARCOS INDEPENDENTES'};document.getElementById('background').onclick=()=>{const light=document.getElementById('scene').classList.toggle('paper');document.getElementById('background').textContent=light?'Fundo escuro':'Fundo claro'};
function advance(seconds){Object.keys(angles).forEach(k=>angles[k]=(angles[k]+seconds*360*directions[k]/periods[k])%360);draw()}
function tick(t){if(last&&playing&&!reference)advance(Math.min((t-last)/1000,.1));last=t;requestAnimationFrame(tick)}draw();requestAnimationFrame(tick);
</script></html>'''
(p/'preview.html').write_text(html)
print('SVG independente e galeria criados')
